export interface ConnectorConfig {
  /** Asana Personal Access Token or OAuth token. */
  asanaAccessToken: string
  /** Asana workspace GID where the task will be created. */
  asanaWorkspaceGid: string
  /** Optional fetch implementation for testing. */
  fetch?: typeof fetch
}

export interface JotformSubmissionPayload {
  id: string
  formId: string
  ip: string
  createdAt: string
  firstName?: string
  lastName?: string
  email?: string
  phone?: string
  company?: string
  message?: string
  answers?: Record<string, string>
}

export interface AsanaTaskResponse {
  gid: string
  name: string
  notes: string
  resource_type: string
}

export interface HandleResult {
  asanaTaskId: string
  asanaTaskName: string
}

function buildTaskName(payload: JotformSubmissionPayload): string {
  const parts: string[] = []
  if (payload.firstName) parts.push(payload.firstName)
  if (payload.lastName) parts.push(payload.lastName)
  if (payload.company) parts.push(payload.company)
  return parts.join(' ') || 'Jotform Submission'
}

function buildTaskNotes(payload: JotformSubmissionPayload): string {
  const lines: string[] = []
  if (payload.email) lines.push(`Email: ${payload.email}`)
  if (payload.phone) lines.push(`Phone: ${payload.phone}`)
  if (payload.message) lines.push(`Message: ${payload.message}`)
  if (payload.answers && Object.keys(payload.answers).length > 0) {
    const answersStr = Object.entries(payload.answers)
      .map(([k, v]) => `${k}=${v}`)
      .join(', ')
    lines.push(`Answers: ${answersStr}`)
  }
  return lines.join('\n')
}

export async function handle(
  payload: JotformSubmissionPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.id) throw new Error('Missing required field: id')
  if (!payload.formId) throw new Error('Missing required field: formId')

  const taskName = buildTaskName(payload)
  const taskNotes = buildTaskNotes(payload)

  const requestBody = {
    data: {
      workspace: config.asanaWorkspaceGid,
      name: taskName,
      notes: taskNotes,
    },
  }

  const response = await fetchImpl('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.asanaAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    throw new Error(`Asana API error: ${response.status} ${response.statusText} at POST https://app.asana.com/api/1.0/tasks`)
  }

  const result = (await response.json()) as { data: AsanaTaskResponse }
  return {
    asanaTaskId: result.data.gid,
    asanaTaskName: result.data.name,
  }
}

